@props(['title' => 'Cartoon Archive', 'url' => null, 'count' => 0, 'endpoint' => null])
<button type="button" class="cartoon-share-btn" data-share-url="{{ $url ?: url()->current() }}" data-share-title="{{ $title }}" data-share-endpoint="{{ $endpoint }}" aria-label="Share {{ $title }}" aria-live="polite"><x-icon name="share" size="16"/> <span>Share</span><b data-share-count>{{ number_format($count) }}</b></button>
<script>
if(!window.__kipanyaShareBound){window.__kipanyaShareBound=true;document.addEventListener('click',async e=>{const b=e.target.closest('[data-share-url]');if(!b)return;const url=b.dataset.shareUrl,title=b.dataset.shareTitle;const endpoint=b.dataset.shareEndpoint; if(endpoint){fetch(endpoint,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||'', 'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{if(d.shares_count!=null){const c=b.querySelector('[data-share-count]');if(c)c.textContent=Number(d.shares_count).toLocaleString();}}).catch(()=>{});} if(navigator.share){try{await navigator.share({title,url})}catch(_){}return}try{await navigator.clipboard.writeText(url);const old=b.innerHTML;b.innerHTML='<span>Copied</span>';setTimeout(()=>b.innerHTML=old,1400)}catch(_){}})}
</script>
